import sys

def smallest_lexicographically(s, investor_indices):
    # List of allowed letters for each investment
    investment_allowances = []
    for index in investor_indices:
        investment_allowances.append(s[index-1])

    # Dictionary to map each letter to its initial position
    initial_positions = {}
    for index, letter in enumerate(s):
        if letter not in initial_positions:
            initial_positions[letter] = index + 1

    # Sort indices of permitted letters based on their initial positions
    permitted_indices = sorted(range(len(investment_allowances)), key=lambda i: initial_positions[investment_allowances[i]])

    # If sorted indices are empty, possible permutation changes can only enhance the lexicographical order
    if not permitted_indices:
        return ''.join(sorted(s))

    # Validate permutations respecting initial positions and investor limits
    def valid_permutation(permutation):
        for i in permitted_indices:
            if permutation[i] not in initial_positions:
                return False
        return True

    for swapped_count in range(1, len(s)):
        for i in range(len(s) - swapped_count + 1):
            # Generate permutations swapping up to swapped_count places
            for j in range(i, len(s) - swapped_count + 1):
                permutation = list(s)
                for k in range(swapped_count):
                    permutation[i + k] = s[k + j + k]
                permutation[j + swapped_count] = s[i + swapped_count]

                # Check if the permutation is valid
                if valid_permutation(permutation):
                    return ''.join(permutation)

    return 'Impossible'

