MOD = 10**9 + 7

# Function to calculate factorial modulo
def factorial(n):
    return 1 if n == 0 else n * (modular_inverse(n + 1) for n in range(1, n))[0]

# Function to calculate modular inverse
def modular_inverse(a):
    return pow(a, MOD - 2, MOD)

# Function to calculate binomial coefficient modulo
