            clusters.add(vertex)

    for vertex in vertices:
        closest_neighbors = [vertex_distances.get(neigh, 0) for neigh in graph[vertex] if neigh in clusters]
        closest_neighbor_index = closest_neighbors.index(min(closest_neighbors))
        closest_neighbor = vertex_distances[min(vertex, max(closest_neighbors))][closest_neighbor_index]
        clusters.add(closest_neighbor)

    return clusters

def make_caterpillar(graph, edge_distances, vertex_distances):
    clusters = find_clusters(edge_distances, vertex_distances)
    merged_distances = {vertex: edge_distances[vertex] + 1 for vertex in vertices if vertex in clusters and vertex_distances[vertex] == 1}
    remaining_vertices = {vertex for vertex in vertices if vertex not in clusters}
    merging_operations_count = 0

    while remaining_vertices:
        min_distance_node = None
        min_distance = float('inf')
        for vertex in remaining_vertices:
            if merged_distances[vertex] < min_distance:
                min_distance_node = vertex
                min_distance = merged_distances[vertex]

        for vertex in graph[min_distance_node]:
            if vertex in merged_distances:
                continue
            edges = merged_distances[min_distance_node] + 1
            total_distance = edge_distances[vertex] + edges
            if total_distance < merged_distances[vertex]:
                merged_distances[vertex] = total_distance
                remaining_vertices -= {vertex}
                merging_operations_count += 1

    return len(vertices) - len(clusters)

