        for num in t:
            xor_of_two = t[i - 1] ^ t[i] ^ num
            if xor_of_two > 0 and xor_of_two in values:
                if dp[i % 2][add] < dp[(i - 1) % 2][num]:
                    dp[i % 2][add] = dp[(i - 1) % 2][num]
                    add = num
            else:
                add = -1
        if add == -1:
            return len(s)
        t.append(add)

