    if parent is not None and parent in parentToChildren[node]: 
        newRoot = parentToChildren[node][parent]
        newParent = get_node_strength(newRoot, parentMapping, parentToChildren, treeNodes)
        return treeNodes[node] + 1 + get_node_strength(parent, parentMapping, parentToChildren, newParent)
    return treeNodes[node] + 1
