from collections import defaultdict

class Tree:
    def __init__(self, size):
        self.size = size
        self.children = [None] * (size + 1)
        self.parents = [0] * (size + 1)

    def dfs(self, node=1):
        for i in range(1, self.size + 1):
            if self.children[i] is not None:
                yield i
                yield from self.dfs(self.children[i])

    def bfs(self, node=1):
        queue = [(node, 1)]
        results = defaultdict(int)
        while queue:
            node, level = queue.pop(0)
            k = (self.size - self.parents[node]) * (level - 1) + 1
            results[k] += 1
            for next_node in self.dfs(node):
                queue.append((next_node, level + 1))
        return results

def count_good_combinations(op):
    t, v, c = op
    tree = Tree(v)
    visited = set()
    while True:
        level = 0
        for new_level in tree.bfs():
            level += new_level // 2
        if v in visited:
            break
        visited.add(v)
    if v > 1:
        return level

