def convert_to_caterpillar(edges):
    indegree = [0] * (num_vertices + 1)
    result = 0
    for a, b in edges:
        indegree[a] += 1
        indegree[b] += 1
    q = [a for a in range(1, num_vertices + 1) if indegree[a] == 1]
    while q:
        vertex = q.pop(0)
        cleanup(vertex, q, indegree)
        result += 1
