from collections import defaultdict

def count_paths(k):
    MAX_VALUE = pow(10, 9) + 7

    tree = defaultdict(lambda: defaultdict(dict))
    for i in range(1, 1 << k):
        vertex = bin(i)[2:]
        vertex = vertex.zfill(k)

        if len(vertex) < k:
            continue

        leaf = vertex[0]
        path = ""

        for j in range(k):
            if j < len(vertex) and vertex[j] == "0":
                leaf += vertex[j:0]
            else:
                leaf += vertex[j:len(vertex)]

            tree[leaf][path] = 1

    def dfs(leaf, path, memo):
        if leaf in memo and path in memo[leaf]:
            return memo[leaf][path][0] + memo[leaf][path][2]

        memo[leaf][path] = [1, 0, 0]

        for _, end, nxt in tree[leaf].items():
            memo[leaf][path] = dfs(end, append(nxt, path, leaf), memo)

        return (memo[leaf][path][0] + memo[leaf][path][2]) % MAX_VALUE

    def append(dest, path, leaf):
        x = len(path)
        if dest[0] != '0':
            return dest
        if x > 0 and dest[1:0] == path[0:x]:
            return dest[0] + path[0:(x - len(path) + 1)]
        if x + 1 > len(dest) and dest[:x + 1] + path[:x] == leaf:
            return dest[:x] + path[:x] + '0'
        dest = dest + path[:x]

        return dest

    def length(dic):
        return max(map(len, dic.values())) + 1
    memo = defaultdict(dict)

    return dfs("0", "", memo)[-1]

